export const A11yBehaviors=function(t){return class extends t{getTextContrastColor(t){let e=t.replace("#","");3===e.length&&(e=e.replace(/./g,t=>t+t));const s=parseInt(e,16),o=s>>8&255,r=255&s,linearize=t=>{const e=t/255;return e<=.03928?e/12.92:Math.pow((e+.055)/1.055,2.4)},n=.2126*linearize(s>>16&255)+.7152*linearize(o)+.0722*linearize(r);return 1.05/(n+.05)>=(n+.05)/.05?"#ffffff":"#000000"}computeTextPropContrast(t,e){if(this[e].includes("#")){const s=this.getTextContrastColor(this[e]);this.set(t,s)}}}};